<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\UserInvitation\Domain\UserInvitationSession;
use Civi\Lughauth\Features\OAuth\UserInvitation\Application\Usecase\Accept\InvitationAcceptParams;
use Civi\Lughauth\Features\OAuth\UserInvitation\Application\Usecase\Accept\InvitationAcceptResult;
use Civi\Lughauth\Features\OAuth\UserInvitation\Application\Usecase\Create\InvitationCreateParams;
use Civi\Lughauth\Features\OAuth\UserInvitation\Application\Usecase\Create\InvitationCreateResult;

final class UserInvitationDomainUnitTest extends TestCase
{
    // --- UserInvitationSession ---

    public function test_user_invitation_session_stores_fields(): void
    {
        $exp = new DateInterval('PT1H');
        $session = new UserInvitationSession('sess-abc', $exp);

        $this->assertSame('sess-abc', $session->sessionId);
        $this->assertSame($exp, $session->expiration);
    }

    // --- InvitationAcceptParams ---

    public function test_invitation_accept_params_stores_fields(): void
    {
        $p = new InvitationAcceptParams(
            rawToken: 'tok-xyz',
            tenantName: 'my-tenant',
            password: 'Secure1!',
            clientId: 'client',
            redirectUri: 'https://app/cb',
        );

        $this->assertSame('tok-xyz', $p->rawToken);
        $this->assertSame('my-tenant', $p->tenantName);
        $this->assertSame('Secure1!', $p->password);
        $this->assertSame('client', $p->clientId);
        $this->assertSame('https://app/cb', $p->redirectUri);
    }

    // --- InvitationAcceptResult ---

    public function test_invitation_accept_result_with_session(): void
    {
        $session = new UserInvitationSession('s', new DateInterval('PT1H'));
        $r = new InvitationAcceptResult('alice@example.com', $session);

        $this->assertSame('alice@example.com', $r->email);
        $this->assertSame($session, $r->session);
    }

    public function test_invitation_accept_result_without_session(): void
    {
        $r = new InvitationAcceptResult('bob@example.com', null);
        $this->assertNull($r->session);
    }

    // --- InvitationCreateParams ---

    public function test_invitation_create_params_stores_required_fields(): void
    {
        $p = new InvitationCreateParams(
            tenantName: 'tenant',
            tenantId: 'tenant-uid',
            email: 'alice@example.com',
            invitedByUserUid: 'admin-uid',
            invitedByEmail: 'admin@example.com',
            baseUrl: 'https://auth.example.com',
        );

        $this->assertSame('tenant', $p->tenantName);
        $this->assertSame('tenant-uid', $p->tenantId);
        $this->assertSame('alice@example.com', $p->email);
        $this->assertSame('admin-uid', $p->invitedByUserUid);
        $this->assertNull($p->roles);
        $this->assertNull($p->metadataJson);
        $this->assertSame('', $p->clientId);
        $this->assertSame('', $p->redirectUri);
    }

    public function test_invitation_create_params_stores_optional_fields(): void
    {
        $p = new InvitationCreateParams(
            tenantName: 'tenant',
            tenantId: 'tid',
            email: 'u@x.com',
            invitedByUserUid: 'uid',
            invitedByEmail: 'a@x.com',
            baseUrl: 'https://auth',
            roles: 'admin,editor',
            metadataJson: '{"dept":"eng"}',
            clientId: 'client',
            redirectUri: 'https://app/cb',
        );

        $this->assertSame('admin,editor', $p->roles);
        $this->assertSame('{"dept":"eng"}', $p->metadataJson);
        $this->assertSame('client', $p->clientId);
    }

    // --- InvitationCreateResult ---

    public function test_invitation_create_result_stores_fields(): void
    {
        $expires = new DateTimeImmutable('2026-06-01T00:00:00+00:00');
        $r = new InvitationCreateResult('inv-uid-123', $expires);

        $this->assertSame('inv-uid-123', $r->uid);
        $this->assertSame($expires, $r->expiresAt);
    }
}
